namespace ghidra.file.formats.android.bootldr;

using ghidra.app.services;
using ghidra.app.services;
using ghidra.app.util.bin;
using ghidra.app.util.importer;
using ghidra.framework.options;
using ghidra.program.model.address;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.util.exception;
using ghidra.util.task;

/**
 * Annotates the structures contained in an Android Boot Loader image.
 */
public class AndroidBootLoaderAnalyzer : AbstractAnalyzer {

	public AndroidBootLoaderAnalyzer() : base("Android Boot Loader", "Annotates the Android Boot Loader header components",
			AnalyzerType.BYTE_ANALYZER)
    {
	}

	/* @Override */
	public bool getDefaultEnablement(Program program) {
		return AndroidBootLoaderConstants.isBootLoader(program);
	}

	/* @Override */
	public bool canAnalyze(Program program) {
		return AndroidBootLoaderConstants.isBootLoader(program);
	}

	/* @Override */
	public void registerOptions(Options options, Program program) {
	}

	/* @Override */
	public bool added(Program program, AddressSetView set, TaskMonitor monitor, MessageLog log)
    {

		AddressSpace addressSpace = program.getAddressFactory().getDefaultAddressSpace();

		Address headerAddress = program.getMinAddress();

		ByteProvider provider = MemoryByteProvider.createProgramHeaderByteProvider(program, false);
		BinaryReader reader = new BinaryReader(provider, !program.getLanguage().isBigEndian());
		try {
			AndroidBootLoaderHeader header = new AndroidBootLoaderHeader(reader);
			DataType headerDataType = header.toDataType();
			Data headerData = program.getListing().createData(headerAddress, headerDataType);
			if (headerData == null) {
				log.appendMsg("Unable to apply header data, stopping.");
				return false;
			}
			SymbolTable symbolTable = program.getSymbolTable();
			Symbol headerSymbol = symbolTable.getPrimarySymbol(headerAddress);
			if (headerSymbol == null) {
				symbolTable.createLabel(headerAddress, header.getMagic(), SourceType.ANALYSIS);
			}
			else {
				headerSymbol.setName(header.getMagic(), SourceType.ANALYSIS);
			}
			int runningOffset = header.getStartOffset();
			foreach (AndroidBootLoaderImageInfo imageInfo in header.getImageInfoList()) {
				Address address = addressSpace.getAddress(runningOffset);
				symbolTable.createLabel(address, imageInfo.getName(), SourceType.ANALYSIS);
				program.getBookmarkManager()
						.setBookmark(address, BookmarkType.ANALYSIS, "boot", imageInfo.getName());
				runningOffset += imageInfo.getSize();
			}
			return true;
		}
		catch (Exception e) {
			log.appendException(e);
		}
		return false;
	}
}
